class PrivateTree:
    def __init__(self, root):
        if sys.platform != "linux":
            raise DomainError("STORE-0001", "Workspace handle provider requires Linux", 503)
        self.root = Path(root)
        if not self.root.is_absolute():
            raise ValueError("Explicit private Workspace root required")
        fd = self._open()
        try:
            info = os.fstat(fd)
            self.identity = info.st_dev, info.st_ino
        finally:
            os.close(fd)

    def _open(self):
        fd = os.open(self.root, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        try:
            self.check(os.fstat(fd), directory=True)
            return fd
        except BaseException:
            os.close(fd)
            raise

    @staticmethod
    def check(info, *, directory=False, device=None):
        if (
            not (stat.S_ISDIR(info.st_mode) if directory else stat.S_ISREG(info.st_mode))
            or info.st_uid != os.geteuid()
            or info.st_mode & 0o7077
            or (not directory and info.st_nlink != 1)
            or (device is not None and info.st_dev != device)
        ):
            raise DomainError("SEC-0021", "Unsafe Workspace handle", 403)

    @contextmanager
    def locked(self):
        import fcntl

        fd = self._open()
        try:
            info = os.fstat(fd)
            if (info.st_dev, info.st_ino) != self.identity:
                raise DomainError("SEC-0021", "Workspace root identity changed", 403)
            fcntl.flock(fd, fcntl.LOCK_EX)

class LocalObjects:
    def __init__(self, root):
        if sys.platform != "linux":
            raise DomainError("STORE-0001", "Local provider requires Linux handle checks", 503)
        self.root = Path(root)
        if not self.root.is_absolute():
            raise ValueError("Explicit absolute object directory required")
        fd = self._open()
        try:
            try:
                info = os.fstat(fd)
            except OSError as error:
                raise _local_provider_unavailable(error) from error
            self.identity = (info.st_dev, info.st_ino)
        finally:
            active_error = sys.exc_info()[0] is not None
            try:
                os.close(fd)
            except OSError as error:
                if not active_error:
                    raise _local_provider_unavailable(error) from error

    def _open(self):
        try:
            fd = os.open(self.root, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        except OSError as error:
            raise _local_provider_unavailable(error) from error
        try:
            info = os.fstat(fd)
        except OSError as error:
            try:
                os.close(fd)
            except OSError:
                # Preserve the first provider failure; neither host detail is public.
                pass
            raise _local_provider_unavailable(error) from error
        if info.st_uid != os.geteuid() or info.st_mode & 0o077:
            try:
                os.close(fd)
            except OSError:
                pass
            raise DomainError("STORE-0001", "Private service-owned directory required", 503)

